import { useEffect, useMemo, useState } from 'react';
import { BrowserRouter, Routes, Route, Navigate, NavLink, useLocation, useNavigate, useParams } from 'react-router-dom';
import { LayoutDashboard, Boxes, Package, ReceiptText, ArrowDownToLine, TriangleAlert, BrainCircuit, ChartNoAxesCombined, Users, Settings as SettingsIcon, LogOut, Bell, Search, Plus, ChevronDown, Menu, X, Eye, Pencil, Trash2, ArrowUpRight, ArrowDownRight, ShoppingCart, IndianRupee, TrendingUp, PackageCheck, Printer, Download, SlidersHorizontal, CircleHelp, Check, ShieldCheck, Mail, LockKeyhole, EyeOff, CalendarDays, MoreHorizontal, FileText, CircleUserRound } from 'lucide-react';
import { AreaChart, Area, ResponsiveContainer, Tooltip, XAxis, YAxis, CartesianGrid, PieChart, Pie, Cell, BarChart, Bar, LineChart, Line } from 'recharts';
import { initialProducts, initialSales, initialUsers, salesSeries } from './data';
import './style.css';

// Shared helpers keep currency, stock states, and browser storage consistent.
const cash=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const stockState=p=>p.qty<=0?'Out of stock':p.qty<=p.min?'Low stock':'In stock';
const read=(key,seed)=>{try{return JSON.parse(localStorage.getItem(key))??seed}catch{return seed}};
function App(){
 // Application state is persisted locally so demos survive page reloads.
 const [products,setProducts]=useState(()=>read('paperlane_products',initialProducts)),[sales,setSales]=useState(()=>read('paperlane_sales',initialSales)),[users,setUsers]=useState(()=>read('paperlane_users',initialUsers)),[moves,setMoves]=useState(()=>read('paperlane_moves',[])),[notices,setNotices]=useState(()=>read('paperlane_notices',[{id:1,title:'Notebook stock is running low',body:'18 units left · Suggested restock: 32',time:'10 min ago',read:false},{id:2,title:'New sale completed',body:'Invoice INV-2408 · ₹1,240',time:'32 min ago',read:false}])),[user,setUser]=useState(()=>read('paperlane_user',null));
 useEffect(()=>localStorage.setItem('paperlane_products',JSON.stringify(products)),[products]);useEffect(()=>localStorage.setItem('paperlane_sales',JSON.stringify(sales)),[sales]);useEffect(()=>localStorage.setItem('paperlane_users',JSON.stringify(users)),[users]);useEffect(()=>localStorage.setItem('paperlane_moves',JSON.stringify(moves)),[moves]);useEffect(()=>localStorage.setItem('paperlane_notices',JSON.stringify(notices)),[notices]);useEffect(()=>{user?localStorage.setItem('paperlane_user',JSON.stringify(user)):localStorage.removeItem('paperlane_user')},[user]);
 const data={products,setProducts,sales,setSales,users,setUsers,moves,setMoves,notices,setNotices,user,setUser};
 return <BrowserRouter><Routes><Route path="/login" element={<AuthPage mode="login" {...data}/>}/><Route path="/register" element={<AuthPage mode="register" {...data}/>}/><Route path="/forgot-password" element={<AuthPage mode="forgot" {...data}/>}/><Route path="/" element={user?<Shell {...data}/>:<Navigate to="/login" replace/>}><Route index element={<Dashboard {...data}/>}/><Route path="inventory" element={<Inventory {...data}/>}/><Route path="products/:id" element={<ProductDetails {...data}/>}/><Route path="billing" element={<Billing {...data}/>}/><Route path="stock" element={<StockManagement {...data}/>}/><Route path="alerts" element={<Alerts {...data}/>}/><Route path="prediction" element={<Prediction {...data}/>}/><Route path="analytics" element={<Analytics {...data}/>}/><Route path="users" element={<UserManagement {...data}/>}/><Route path="settings" element={<Settings {...data}/>}/></Route><Route path="*" element={<Navigate to="/" replace/>}/></Routes></BrowserRouter>
}

// Authentication pages share one polished form shell and use mock local login.
function AuthPage({mode,setUser}){const nav=useNavigate(),[show,setShow]=useState(false),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');const title=mode==='register'?'Create your account':mode==='forgot'?'Reset your password':'Welcome back';
 function submit(e){e.preventDefault();setMsg('');const f=new FormData(e.currentTarget),email=f.get('email');if(!/^\S+@\S+\.\S+$/.test(email)){setMsg('Enter a valid email address.');return}if(mode==='forgot'){setMsg('If an account exists, password reset instructions are ready for your email.');return}if(mode==='register'&&f.get('password')!==f.get('confirm')){setMsg('Your passwords do not match.');return}if((f.get('password')||'').length<6){setMsg('Use at least 6 characters for your password.');return}setBusy(true);setTimeout(()=>{setUser({name:mode==='register'?f.get('name'):'Roshan Kumar',email});setBusy(false);nav('/')},500)}
 return <div className="auth-page"><div className="auth-brand"><div className="brand-lockup"><span className="brand-mark"><Boxes size={23}/></span><span>paperlane<span className="brand-dot">.</span></span></div><div className="auth-visual"><div className="visual-orb orb-a"/><div className="visual-orb orb-b"/><div className="visual-card card-front"><div className="visual-header"><span>Today’s revenue</span><ArrowUpRight size={16}/></div><strong>₹24,680</strong><div className="visual-bars">{[40,58,48,73,60,88,70,95,78,100,83,92].map((h,i)=><i key={i} style={{height:`${h}%`}}/>)}</div><small>+18.6% <span>compared to last week</span></small></div><div className="visual-card card-back"><span className="product-emoji">📓</span><div><b>Classic Notebook</b><small>Stock level <em>Low stock</em></small></div><span className="stock-count">18</span></div><div className="auth-quote"><span>INVENTORY, IN GOOD COMPANY.</span><h2>Keep your business<br/>moving forward.</h2><p>Smarter stock decisions. Happier customers. All in one place.</p></div></div><div className="auth-brand-foot">© 2025 Paperlane · Built for growing businesses</div></div><div className="auth-form-side"><form className="auth-form" onSubmit={submit}><div className="auth-mobile-brand brand-lockup"><span className="brand-mark"><Boxes size={22}/></span><span>paperlane<span className="brand-dot">.</span></span></div><div className="eyebrow">{mode==='register'?'GET STARTED':mode==='forgot'?'ACCOUNT RECOVERY':'YOUR WORKSPACE'}</div><h1>{title}</h1><p className="auth-sub">{mode==='register'?'Start managing your inventory with clarity.':mode==='forgot'?'Enter your account email and we’ll help you reset it.':'Sign in to your workspace to pick up where you left off.'}</p>{mode==='register'&&<Field label="Full name" name="name" placeholder="Your name" required/>}<Field label="Email address" name="email" type="email" placeholder="you@company.com" required/>{mode!=='forgot'&&<div className="field"><label>Password</label><div className="password-wrap"><input name="password" type={show?'text':'password'} placeholder="Enter your password" required/><button type="button" className="icon-button" onClick={()=>setShow(!show)} aria-label="Toggle password visibility">{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></div>}{mode==='register'&&<Field label="Phone number" name="phone" placeholder="+91 98765 43210"/>}{mode==='register'&&<Field label="Confirm password" name="confirm" type="password" placeholder="Re-enter your password" required/>}{mode==='login'&&<div className="form-between"><label className="check-label"><input type="checkbox"/> Remember me</label><a href="/forgot-password">Forgot password?</a></div>}{msg&&<div className="form-message">{msg}</div>}<button className="button primary full" disabled={busy}>{busy?<><span className="spinner"/>Signing in…</>:mode==='register'?'Create account':mode==='forgot'?'Send reset link':'Sign in'}<ArrowUpRight size={17}/></button><div className="auth-switch">{mode==='login'?<>New to Paperlane? <a href="/register">Create an account</a></>:<>Already have an account? <a href="/login">Sign in</a></>}</div><div className="demo-tip"><ShieldCheck size={16}/><span>Demo mode · Any valid email and password (6+ characters) works.</span></div><div className="auth-security"><LockKeyhole size={13}/> Secure workspace <span>·</span> Privacy first</div></form></div></div>}
function Field({label,name,type='text',placeholder,required,defaultValue,value,onChange}){return <div className="field"><label htmlFor={name}>{label}</label><input id={name} name={name} type={type} placeholder={placeholder} required={required} defaultValue={defaultValue} value={value} onChange={onChange}/></div>}

const navItems=[['Overview','/','LayoutDashboard'],['Inventory','/inventory','Package'],['Billing & sales','/billing','ReceiptText'],['Stock management','/stock','ArrowDownToLine'],['Low stock alerts','/alerts','TriangleAlert'],['AI demand prediction','/prediction','BrainCircuit'],['Analytics & reports','/analytics','ChartNoAxesCombined'],['User management','/users','Users'],['Settings','/settings','Settings']];
const iconMap={LayoutDashboard,Package,ReceiptText,ArrowDownToLine,TriangleAlert,BrainCircuit,ChartNoAxesCombined,Users,Settings:SettingsIcon};
// Shell holds navigation, search, notification tray, and route-level page chrome.
function Shell(p){const loc=useLocation(),nav=useNavigate(),[mobile,setMobile]=useState(false),[collapsed,setCollapsed]=useState(false),[search,setSearch]=useState(''),[searchOpen,setSearchOpen]=useState(false),[noticeOpen,setNoticeOpen]=useState(false),[profileOpen,setProfileOpen]=useState(false);const active=navItems.find(n=>n[1]===loc.pathname);const title=loc.pathname.startsWith('/products/')?'Product details':active?.[0]||'Overview';const unread=p.notices.filter(n=>!n.read).length;
 return <div className={`app-shell ${collapsed?'sidebar-collapsed':''}`}><aside className={`sidebar ${mobile?'mobile-open':''}`}><div className="side-brand"><span className="brand-mark"><Boxes size={21}/></span>{!collapsed&&<span>paperlane<span className="brand-dot">.</span></span>}<button className="mobile-close icon-button" onClick={()=>setMobile(false)}><X size={19}/></button></div><div className="workspace-chip"><span className="workspace-avatar">P</span>{!collapsed&&<span><b>Paperlane Stationery</b><small>Retail workspace</small></span>}<ChevronDown size={15}/></div><div className="nav-caption">WORKSPACE</div><nav>{navItems.map(([label,path,icon])=>{const I=iconMap[icon];return <NavLink key={path} end={path==='/'} to={path} onClick={()=>setMobile(false)} className={({isActive})=>`nav-link ${isActive?'selected':''}`}><I size={18}/>{!collapsed&&<span>{label}</span>}{path==='/alerts'&&p.products.filter(x=>x.qty<=x.min).length>0&&!collapsed&&<b className="nav-count">{p.products.filter(x=>x.qty<=x.min).length}</b>}</NavLink>})}</nav><div className="sidebar-bottom"><div className="help-box"><CircleHelp size={18}/>{!collapsed&&<div><b>Need a hand?</b><small>Visit our help center</small></div>}<ArrowUpRight size={14}/></div><button className="user-mini" onClick={()=>setProfileOpen(!profileOpen)}><span className="avatar">{(p.user?.name||'R')[0]}</span>{!collapsed&&<span><b>{p.user?.name||'Roshan Kumar'}</b><small>Administrator</small></span>}<MoreHorizontal size={17}/></button></div><button className="collapse-btn" onClick={()=>setCollapsed(!collapsed)}>{collapsed?<ArrowUpRight size={16}/>:<span>Collapse sidebar</span>} {!collapsed&&<span>‹</span>}</button></aside><main className="main-area"><header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMobile(true)}><Menu size={20}/></button><div className="breadcrumbs"><span>Workspace</span><span className="crumb-sep">/</span><b>{title}</b></div><div className="top-actions"><div className={`top-search ${searchOpen?'search-visible':''}`}><Search size={17}/><input placeholder="Search anything…" value={search} onChange={e=>setSearch(e.target.value)}/><kbd>⌘ K</kbd></div><button className="icon-button search-mobile" onClick={()=>setSearchOpen(!searchOpen)}><Search size={19}/></button><div className="popover-anchor"><button className="icon-button notification-button" onClick={()=>setNoticeOpen(!noticeOpen)} aria-label="Notifications"><Bell size={19}/>{unread>0&&<i>{unread}</i>}</button>{noticeOpen&&<div className="popover notice-popover"><div className="popover-head"><b>Notifications</b><button onClick={()=>p.setNotices(p.notices.map(n=>({...n,read:true})))}>Mark all read</button></div>{p.notices.slice(0,5).map(n=><div className={`notice-row ${n.read?'':'unread'}`} key={n.id}><span className="notice-icon"><Bell size={15}/></span><div><b>{n.title}</b><p>{n.body}</p><small>{n.time}</small></div></div>)}</div>}</div><div className="profile-anchor popover-anchor"><button className="profile-trigger" onClick={()=>setProfileOpen(!profileOpen)}><span className="avatar">{(p.user?.name||'R')[0]}</span><span className="profile-name"><b>{p.user?.name||'Roshan Kumar'}</b><small>Admin</small></span><ChevronDown size={15}/></button>{profileOpen&&<div className="popover profile-popover"><button onClick={()=>{nav('/settings');setProfileOpen(false)}}><SettingsIcon size={16}/> Account settings</button><button onClick={()=>{p.setUser(null);nav('/login')}}><LogOut size={16}/> Sign out</button></div>}</div></div></header><div className="content"><Routes><Route index element={<Dashboard {...p}/>}/><Route path="inventory" element={<Inventory {...p}/>}/><Route path="products/:id" element={<ProductDetails {...p}/>}/><Route path="billing" element={<Billing {...p}/>}/><Route path="stock" element={<StockManagement {...p}/>}/><Route path="alerts" element={<Alerts {...p}/>}/><Route path="prediction" element={<Prediction {...p}/>}/><Route path="analytics" element={<Analytics {...p}/>}/><Route path="users" element={<UserManagement {...p}/>}/><Route path="settings" element={<Settings {...p}/>}/></Routes></div></main>{mobile&&<button className="scrim" onClick={()=>setMobile(false)}/>}</div>
}

// Small reusable pieces standardize page headers, tags, and status appearance.
function PageHead({eyebrow,title,sub,actions}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{sub&&<p>{sub}</p>}</div>{actions&&<div className="head-actions">{actions}</div>}</div>}
function Button({children,variant='secondary',onClick,icon:Icon,disabled,type='button'}){return <button type={type} disabled={disabled} className={`button ${variant}`} onClick={onClick}>{Icon&&<Icon size={16}/>}<span>{children}</span></button>}
function Status({product}){const s=stockState(product);return <span className={`status ${s==='In stock'?'green':s==='Low stock'?'orange':'red'}`}><i/>{s}</span>}
function StatCard({label,value,change,icon:Icon,tone='blue',foot}){return <article className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={19}/></div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-foot"><span className={change?.startsWith('-')?'negative':'positive'}>{change?.startsWith('-')?<ArrowDownRight size={14}/>:<ArrowUpRight size={14}/>} {change}</span><span>{foot||'vs. last month'}</span></div></article>}
function Panel({title,sub,action,children,className=''}){return <section className={`panel ${className}`}><div className="panel-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>}
const chartTip={contentStyle:{border:'1px solid #edf0f5',borderRadius:10,boxShadow:'0 8px 24px #17233b12',fontSize:12},labelStyle:{color:'#718096',fontWeight:600},itemStyle:{color:'#3455db'}};

// Dashboard summarizes stock, sales, trend charts, and operational alerts.
function Dashboard({products,sales,notices,setNotices}){const [range,setRange]=useState('7 days'),low=products.filter(p=>p.qty<=p.min),value=products.reduce((a,p)=>a+p.cost*p.qty,0),pie=[{name:'In stock',value:products.filter(p=>p.qty>p.min).length,color:'#3fb58d'},{name:'Low stock',value:products.filter(p=>p.qty>0&&p.qty<=p.min).length,color:'#f1a64a'},{name:'Out of stock',value:products.filter(p=>p.qty===0).length,color:'#ee6f76'}];return <><PageHead eyebrow="TUESDAY, 03 NOVEMBER 2026" title="Good morning, Roshan" sub="Here's what's happening with your inventory and sales today." actions={<button className="date-filter"><CalendarDays size={16}/> Today <ChevronDown size={14}/></button>}/><div className="stats-grid"><StatCard label="Total products" value={products.length} change="8.2%" icon={Package} tone="blue"/><StatCard label="Low stock items" value={low.length} change="2 need attention" icon={TriangleAlert} tone="orange"/><StatCard label="Today's sales" value={cash(8000)} change="12.8%" icon={IndianRupee} tone="green"/><StatCard label="Inventory value" value={cash(value)} change="4.6%" icon={Boxes} tone="violet"/></div><div className="dashboard-grid top-grid"><Panel title="Sales overview" sub="Revenue performance over time" action={<select className="select-compact" value={range} onChange={e=>setRange(e.target.value)}><option>7 days</option><option>30 days</option><option>90 days</option></select>}><div className="chart-summary"><strong>₹45,700</strong><span className="positive"><ArrowUpRight size={14}/> 12.8%</span><small>vs previous period</small></div><ResponsiveContainer width="100%" height={210}><AreaChart data={salesSeries}><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4a67e8" stopOpacity={.2}/><stop offset="100%" stopColor="#4a67e8" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#eef1f6" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#9aa4b4'}} dy={8}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#9aa4b4'}} tickFormatter={v=>`₹${v/1000}k`}/><Tooltip {...chartTip} formatter={v=>cash(v)}/><Area type="monotone" dataKey="sales" stroke="#4c64df" strokeWidth={2.5} fill="url(#salesFill)"/></AreaChart></ResponsiveContainer></Panel><Panel title="Inventory overview" sub="Stock health across all products"><div className="inventory-chart"><div className="donut-wrap"><ResponsiveContainer width="100%" height={170}><PieChart><Pie data={pie} dataKey="value" innerRadius={54} outerRadius={72} paddingAngle={4} stroke="none">{pie.map(x=><Cell key={x.name} fill={x.color}/>)}</Pie></PieChart></ResponsiveContainer><div className="donut-center"><b>{products.length}</b><small>products</small></div></div><div className="legend-list">{pie.map(x=><div key={x.name}><span><i style={{background:x.color}}/>{x.name}</span><b>{x.value}</b></div>)}</div></div></Panel></div><div className="dashboard-grid lower-grid"><Panel title="Products to watch" sub="A little attention goes a long way" action={<a className="text-link" href="/alerts">View all <ArrowUpRight size={14}/></a>}><div className="watch-list">{low.slice(0,4).map(p=><div className="watch-row" key={p.id}><span className="product-icon">{p.icon}</span><div className="watch-product"><b>{p.name}</b><small>{p.category} · Min. {p.min} units</small></div><div className="watch-stock"><strong>{p.qty}</strong><small>in stock</small></div><Button variant="tiny" onClick={()=>location.assign('/stock')}>Restock</Button></div>)}</div>{!low.length&&<div className="empty-state">Everything is well stocked. Nice work!</div>}</Panel><Panel title="Top selling products" sub="By units sold this month" action={<a className="text-link" href="/analytics">See report <ArrowUpRight size={14}/></a>}><div className="top-products">{[...products].sort((a,b)=>b.sold-a.sold).slice(0,4).map((p,i)=><div className="top-product-row" key={p.id}><span className="rank">0{i+1}</span><span className="product-icon">{p.icon}</span><b>{p.name}</b><span className="units-sold">{p.sold} sold</span><strong>{cash(p.sold*p.price)}</strong></div>)}</div></Panel></div><div className="dashboard-grid insight-grid"><div className="insight-card"><div className="insight-badge"><BrainCircuit size={16}/> SMART INSIGHT</div><h3>Your next best move</h3><p>Notebook demand is trending <b>up 24%</b> this week. Restock 32 units to stay ahead of projected demand.</p><a href="/prediction">Explore demand insights <ArrowUpRight size={15}/></a><div className="insight-art">✳</div></div><Panel title="Recent transactions" sub="Latest completed sales" action={<a className="text-link" href="/billing">All sales <ArrowUpRight size={14}/></a>}><Transactions sales={sales.slice(0,3)}/></Panel></div></>}
function Transactions({sales}){return <div className="transaction-list">{sales.map(s=><div className="transaction-row" key={s.id}><span className="transaction-icon"><ReceiptText size={17}/></span><div><b>{s.id}</b><small>{s.customer} · {s.date}</small></div><strong>{cash(s.amount)}</strong><span className="paid-tag">Paid</span></div>)}</div>}

// Inventory table supports add/edit/delete, filters, sorting, and paging.
function Inventory({products,setProducts}){const [query,setQuery]=useState(''),[category,setCategory]=useState('All categories'),[status,setStatus]=useState('All stock'),[page,setPage]=useState(1),[modal,setModal]=useState(null);const [sort,setSort]=useState('name');const cats=['All categories',...new Set(products.map(p=>p.category))];const filtered=useMemo(()=>products.filter(p=>(p.name.toLowerCase().includes(query.toLowerCase())||p.id.toLowerCase().includes(query.toLowerCase()))&&(category==='All categories'||p.category===category)&&(status==='All stock'||stockState(p)===status)).sort((a,b)=>String(a[sort]).localeCompare(String(b[sort]),undefined,{numeric:true})),[products,query,category,status,sort]);const rows=filtered.slice((page-1)*6,page*6);function save(form){if(modal?.id)setProducts(products.map(p=>p.id===modal.id?{...modal,...form}:p));else setProducts([{...form,id:form.id||`ST-${Date.now().toString().slice(-5)}`,sold:0,icon:'📦'},...products]);setModal(null)}return <><PageHead eyebrow="CATALOG" title="Inventory" sub="Keep your products organized and your stock in check." actions={<Button variant="primary" icon={Plus} onClick={()=>setModal({})}>Add product</Button>}/><div className="inventory-summary-strip"><div><span className="strip-icon"><Package size={18}/></span><span><b>{products.length} products</b><small>Across {new Set(products.map(p=>p.category)).size} categories</small></span></div><span className="strip-divider"/><div><span className="strip-icon orange"><TriangleAlert size={18}/></span><span><b>{products.filter(p=>p.qty<=p.min).length} need attention</b><small>Low or out of stock</small></span></div><span className="strip-divider"/><div><span className="strip-icon green"><IndianRupee size={18}/></span><span><b>{cash(products.reduce((a,p)=>a+p.qty*p.cost,0))}</b><small>Inventory value</small></span></div></div><section className="panel table-panel"><div className="table-toolbar"><div><h3>All products <span className="count-pill">{filtered.length}</span></h3><p>A complete list of your inventory.</p></div><div className="filters"><div className="table-search"><Search size={16}/><input placeholder="Search products…" value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}}/></div><select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{cats.slice(1).map(c=><option key={c}>{c}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option>All stock</option><option>In stock</option><option>Low stock</option><option>Out of stock</option></select><button className="square-filter"><SlidersHorizontal size={16}/></button></div></div><div className="table-scroll"><table><thead><tr><th><input type="checkbox"/></th><th onClick={()=>setSort('name')}>PRODUCT <ChevronDown size={12}/></th><th onClick={()=>setSort('category')}>CATEGORY</th><th onClick={()=>setSort('price')}>PRICE</th><th onClick={()=>setSort('qty')}>AVAILABLE</th><th>MIN. LEVEL</th><th>STATUS</th><th/></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><input type="checkbox"/></td><td><a className="table-product" href={`/products/${p.id}`}><span className="product-icon">{p.icon}</span><span><b>{p.name}</b><small>{p.id}</small></span></a></td><td><span className="category-tag">{p.category}</span></td><td>{cash(p.price)}</td><td><b>{p.qty}</b> <span className="muted">units</span></td><td>{p.min} units</td><td><Status product={p}/></td><td><div className="row-actions"><button title="View product" onClick={()=>location.assign(`/products/${p.id}`)}><Eye size={16}/></button><button title="Edit product" onClick={()=>setModal({...p})}><Pencil size={15}/></button><button title="Delete product" onClick={()=>confirm(`Delete ${p.name}?`)&&setProducts(products.filter(x=>x.id!==p.id))}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-state">No products match these filters.</div>}</div><div className="table-footer"><span>Showing {filtered.length?((page-1)*6+1):0}–{Math.min(page*6,filtered.length)} of {filtered.length} products</span><div><button disabled={page===1} onClick={()=>setPage(page-1)}>Previous</button><button className="page-number">{page}</button><button disabled={page*6>=filtered.length} onClick={()=>setPage(page+1)}>Next</button></div></div></section>{modal&&<ProductModal product={modal} onClose={()=>setModal(null)} onSave={save}/>}</>}
function ProductModal({product,onClose,onSave}){const [error,setError]=useState('');function submit(e){e.preventDefault();const f=new FormData(e.currentTarget),v=Object.fromEntries(f.entries());if(+v.price<=0||+v.qty<0||+v.min<0){setError('Enter a valid price and non-negative stock quantities.');return}onSave({...product,...v,price:+v.price,cost:+v.cost,qty:+v.qty,min:+v.min})}return <Modal title={product.id?'Edit product':'Add a product'} onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="form-grid"><Field label="Product name" name="name" placeholder="e.g. Ruled notebook" required defaultValue={product.name}/><Field label="Product ID / SKU" name="id" placeholder="Auto-generated if empty" defaultValue={product.id}/><label className="field"><span>Category</span><select name="category" defaultValue={product.category||'Writing'}>{['Writing','Notebooks','Paper','Files','Bags','Accessories'].map(x=><option>{x}</option>)}</select></label><Field label="Supplier name" name="supplier" placeholder="Supplier" defaultValue={product.supplier}/><Field label="Purchase price (₹)" name="cost" type="number" placeholder="0" required defaultValue={product.cost||''}/><Field label="Selling price (₹)" name="price" type="number" placeholder="0" required defaultValue={product.price||''}/><Field label="Available quantity" name="qty" type="number" placeholder="0" required defaultValue={product.qty??''}/><Field label="Minimum stock level" name="min" type="number" placeholder="0" required defaultValue={product.min??''}/></div>{error&&<div className="form-message">{error}</div>}<div className="modal-actions"><Button onClick={onClose}>Cancel</Button><Button variant="primary" type="submit">Save product</Button></div></form></Modal>}
function Modal({title,onClose,children}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal"><div className="modal-head"><div><div className="eyebrow">INVENTORY CATALOG</div><h2>{title}</h2></div><button className="icon-button" onClick={onClose}><X size={18}/></button></div>{children}</section></div>}

// Product details present stock position and history with edit access.
function ProductDetails({products,setProducts,moves,sales}){const {id}=useParams(),nav=useNavigate(),p=products.find(x=>x.id===id);const [editing,setEditing]=useState(false);if(!p)return <><PageHead title="Product not found"/><Button onClick={()=>nav('/inventory')}>Back to inventory</Button></>;return <><div className="back-line"><button onClick={()=>nav('/inventory')}>← Back to inventory</button><span>/</span>{p.name}</div><PageHead eyebrow={p.id} title={p.name} sub={`${p.category} · Supplied by ${p.supplier}`} actions={<Button icon={Pencil} onClick={()=>setEditing(true)}>Edit product</Button>}/><div className="product-detail-grid"><Panel title="Product overview" sub="Product information and current position"><div className="product-hero"><div className="product-hero-icon">{p.icon}</div><div><Status product={p}/><h2>{p.name}</h2><span>{p.id} · {p.category}</span></div></div><div className="detail-metrics"><div><small>Selling price</small><b>{cash(p.price)}</b></div><div><small>Purchase price</small><b>{cash(p.cost)}</b></div><div><small>Current stock</small><b>{p.qty} units</b></div><div><small>Minimum level</small><b>{p.min} units</b></div></div><div className="detail-line"><span>Supplier</span><b>{p.supplier}</b></div><div className="detail-line"><span>Gross margin</span><b>{Math.round((p.price-p.cost)/p.price*100)}%</b></div></Panel><Panel title="Recent stock activity" sub="Latest movements for this product"><MovementTable moves={moves.filter(x=>x.product===p.name).slice(0,6)}/></Panel><Panel title="Product performance" sub="Sales activity"><div className="performance-card"><div><span className="stat-icon blue"><TrendingUp size={18}/></span><small>Units sold</small><b>{p.sold}</b></div><div><span className="stat-icon green"><IndianRupee size={18}/></span><small>Sales revenue</small><b>{cash(p.sold*p.price)}</b></div></div></Panel></div>{editing&&<ProductModal product={p} onClose={()=>setEditing(false)} onSave={v=>{setProducts(products.map(x=>x.id===p.id?v:x));setEditing(false)}}/>}</>}
function MovementTable({moves}){return moves.length?<div className="movement-list">{moves.map(m=><div className="movement-row" key={m.id}><span className={`movement-icon ${m.type==='Stock in'?'green':'orange'}`}>{m.type==='Stock in'?<ArrowDownToLine size={16}/>:<ArrowUpRight size={16}/>}</span><div><b>{m.type}</b><small>{m.date}</small></div><span>{m.previous} → {m.updated}</span><strong className={m.type==='Stock in'?'positive':'negative'}>{m.type==='Stock in'?'+':'−'}{m.qty}</strong></div>)}</div>:<div className="empty-state">No stock movements recorded yet.</div>}

// Billing handles cart math, validates stock, records sales, and prints invoices.
function Billing({products,setProducts,sales,setSales,setMoves,setNotices}){const [query,setQuery]=useState(''),[cart,setCart]=useState([]),[customer,setCustomer]=useState(''),[phone,setPhone]=useState(''),[discount,setDiscount]=useState(0),[tax,setTax]=useState(5),[invoice,setInvoice]=useState(null),[toast,setToast]=useState('');const shown=products.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())&&p.qty>0);const subtotal=cart.reduce((a,c)=>a+c.qty*c.price,0),total=Math.max(0,subtotal*(1+Number(tax)/100)-Number(discount));function add(p){setCart(c=>{const old=c.find(x=>x.id===p.id);if(old)return c.map(x=>x.id===p.id?{...x,qty:Math.min(x.qty+1,p.qty)}:x);return [...c,{...p,qty:1}]})}function complete(){if(!cart.length){setToast('Add products to the cart first.');return}if(cart.some(c=>c.qty>products.find(p=>p.id===c.id).qty)){setToast('Cart quantity exceeds available stock.');return}if(!customer.trim()){setToast('Enter a customer name to generate the bill.');return}const id=`INV-${Date.now().toString().slice(-6)}`,record={id,customer,date:new Date().toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}),amount:Math.round(total),status:'Paid',items:cart.map(({id,name,qty,price})=>({id,name,qty,price})),subtotal,discount:Number(discount),tax:Number(tax)};setProducts(products.map(p=>{const item=cart.find(c=>c.id===p.id);if(!item)return p;setMoves(m=>[{id:Date.now()+p.id,product:p.name,type:'Stock out',qty:item.qty,previous:p.qty,updated:p.qty-item.qty,date:'Just now'},...m]);return {...p,qty:p.qty-item.qty,sold:p.sold+item.qty}}));setSales([record,...sales]);setNotices(n=>[{id:Date.now(),title:'Sale completed successfully',body:`Invoice ${id} · ${cash(total)}`,time:'Just now',read:false},...n]);setInvoice(record);setCart([]);setToast('Invoice generated and inventory updated.')}return <><PageHead eyebrow="CHECKOUT" title="Billing & sales" sub="Build a sale, take payment, and create a polished invoice." actions={<span className="invoice-number"><FileText size={16}/> New invoice · {new Date().toLocaleDateString('en-IN')}</span>}/><div className="billing-layout"><Panel title="Select products" sub={`${shown.length} products available`} action={<div className="table-search"><Search size={15}/><input placeholder="Find a product…" value={query} onChange={e=>setQuery(e.target.value)}/></div>}><div className="billing-products">{shown.map(p=><button className="billing-product" key={p.id} onClick={()=>add(p)}><span className="product-icon big">{p.icon}</span><b>{p.name}</b><small>{p.qty} in stock</small><strong>{cash(p.price)}</strong><span className="add-to-cart"><Plus size={14}/> Add</span></button>)}</div></Panel><section className="panel cart-panel"><div className="panel-head"><div><h3>Current sale</h3><p>{cart.length} items in your cart</p></div><span className="cart-head-icon"><ShoppingCart size={17}/></span></div><div className="cart-items">{cart.map(c=><div className="cart-row" key={c.id}><span className="product-icon">{c.icon}</span><div className="cart-item-name"><b>{c.name}</b><small>{cash(c.price)} / unit</small></div><div className="quantity-control"><button onClick={()=>setCart(cart.map(x=>x.id===c.id?{...x,qty:Math.max(1,x.qty-1)}:x))}>−</button><span>{c.qty}</span><button onClick={()=>setCart(cart.map(x=>x.id===c.id?{...x,qty:Math.min(products.find(p=>p.id===x.id).qty,x.qty+1)}:x))}>+</button></div><b>{cash(c.price*c.qty)}</b><button className="remove-item" onClick={()=>setCart(cart.filter(x=>x.id!==c.id))}><X size={14}/></button></div>)}{!cart.length&&<div className="cart-empty"><span><ShoppingCart size={22}/></span><b>Your cart is empty</b><small>Add products to start a sale.</small></div>}</div><div className="customer-fields"><label className="field">Customer name<input value={customer} onChange={e=>setCustomer(e.target.value)} placeholder="Walk-in customer"/></label><label className="field">Phone number<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Optional"/></label></div><div className="billing-options"><label>Discount <span><input type="number" min="0" value={discount} onChange={e=>setDiscount(e.target.value)}/> ₹</span></label><label>Tax <span><input type="number" min="0" value={tax} onChange={e=>setTax(e.target.value)}/> %</span></label></div><div className="bill-totals"><div><span>Subtotal</span><b>{cash(subtotal)}</b></div><div><span>Tax ({tax}%)</span><b>{cash(subtotal*tax/100)}</b></div><div><span>Discount</span><b>− {cash(discount)}</b></div><div className="grand-total"><strong>Total due</strong><strong>{cash(total)}</strong></div></div>{toast&&<div className="form-message">{toast}</div>}<div className="cart-actions"><Button onClick={()=>{setCart([]);setToast('')}}>Clear cart</Button><Button variant="primary" icon={Check} onClick={complete}>Generate bill</Button></div></section></div><Panel title="Recent sales" sub="Latest invoices created from this workspace" className="recent-sales-panel"><Transactions sales={sales.slice(0,5)}/></Panel>{invoice&&<InvoiceModal invoice={invoice} phone={phone} onClose={()=>setInvoice(null)}/>}</>}
function InvoiceModal({invoice,phone,onClose}){return <div className="modal-backdrop"><section className="invoice-modal"><div className="invoice-modal-actions"><span className="paid-tag">Invoice ready</span><div><Button icon={Printer} onClick={()=>window.print()}>Print invoice</Button><button className="icon-button" onClick={onClose}><X size={18}/></button></div></div><div className="print-invoice"><div className="invoice-top"><div className="brand-lockup"><span className="brand-mark"><Boxes size={19}/></span><span>paperlane<span className="brand-dot">.</span></span></div><div><b>TAX INVOICE</b><small>{invoice.id}</small></div></div><div className="invoice-meta"><div><small>BILLED TO</small><b>{invoice.customer}</b>{phone&&<span>{phone}</span>}</div><div><small>INVOICE DATE</small><b>{invoice.date}</b></div></div><table><thead><tr><th>ITEM</th><th>QTY</th><th>PRICE</th><th>AMOUNT</th></tr></thead><tbody>{invoice.items.map(i=><tr key={i.id}><td>{i.name}</td><td>{i.qty}</td><td>{cash(i.price)}</td><td>{cash(i.price*i.qty)}</td></tr>)}</tbody></table><div className="invoice-total"><div><span>Subtotal</span><b>{cash(invoice.subtotal)}</b></div><div><span>Tax ({invoice.tax}%)</span><b>{cash(invoice.subtotal*invoice.tax/100)}</b></div><div><span>Discount</span><b>− {cash(invoice.discount)}</b></div><div className="grand-total"><strong>Total paid</strong><strong>{cash(invoice.amount)}</strong></div></div><p className="invoice-thanks">Thank you for shopping with Paperlane.</p></div></section></div>}

// Stock operations log every change so later audit views use the same schema.
function StockManagement({products,setProducts,moves,setMoves}){const [form,setForm]=useState({product:'',qty:'',supplier:'',notes:''}),[query,setQuery]=useState(''),[msg,setMsg]=useState('');function receive(e){e.preventDefault();const p=products.find(x=>x.id===form.product),q=Number(form.qty);if(!p||q<=0){setMsg('Choose a product and enter a quantity greater than zero.');return}setProducts(products.map(x=>x.id===p.id?{...x,qty:x.qty+q,supplier:form.supplier||x.supplier}:x));setMoves([{id:Date.now(),product:p.name,type:'Stock in',qty:q,previous:p.qty,updated:p.qty+q,date:new Date().toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}),supplier:form.supplier,notes:form.notes},...moves]);setMsg(`${q} units added to ${p.name}.`);setForm({product:'',qty:'',supplier:'',notes:''})}return <><PageHead eyebrow="INVENTORY CONTROL" title="Stock management" sub="Track stock movements and keep every adjustment accountable."/><div className="stats-grid stock-stats"><StatCard label="Total units on hand" value={products.reduce((a,p)=>a+p.qty,0)} change="Across all products" icon={Boxes} tone="blue"/><StatCard label="Stock received" value={moves.filter(x=>x.type==='Stock in').reduce((a,x)=>a+x.qty,0)} change="Logged movements" icon={ArrowDownToLine} tone="green"/><StatCard label="Stock deducted" value={moves.filter(x=>x.type==='Stock out').reduce((a,x)=>a+x.qty,0)} change="From sales" icon={ArrowUpRight} tone="orange"/><StatCard label="Adjustments" value={moves.filter(x=>x.type==='Adjustment').length} change="Manual changes" icon={SlidersHorizontal} tone="violet"/></div><div className="stock-layout"><Panel title="Receive stock" sub="Record a new delivery or replenishment"><form className="stock-form" onSubmit={receive}><label className="field">Select product<select required value={form.product} onChange={e=>setForm({...form,product:e.target.value})}><option value="">Choose a product</option>{products.map(p=><option value={p.id}>{p.name} · {p.qty} on hand</option>)}</select></label><Field label="Quantity received" name="qty" type="number" placeholder="e.g. 24" required value={form.qty} onChange={e=>setForm({...form,qty:e.target.value})}/><Field label="Supplier" name="supplier" placeholder="Supplier name" value={form.supplier} onChange={e=>setForm({...form,supplier:e.target.value})}/><label className="field">Notes<textarea placeholder="Purchase order, delivery notes…" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label>{msg&&<div className={msg.includes('added')?'success-message':'form-message'}>{msg}</div>}<Button variant="primary" icon={Plus} type="submit">Record stock in</Button></form></Panel><Panel title="Stock by product" sub="Current available quantities" className="stock-level-panel"><div className="table-search stock-search"><Search size={15}/><input placeholder="Search products" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="stock-level-list">{products.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())).map(p=><div className="stock-level-row" key={p.id}><span className="product-icon">{p.icon}</span><div><b>{p.name}</b><small>{p.id}</small></div><div className="stock-bar"><i style={{width:`${Math.min(100,(p.qty/Math.max(p.min*3,1))*100)}%`,background:p.qty<=p.min?'#eba647':'#5270e7'}}/></div><b>{p.qty}</b><Status product={p}/></div>)}</div></Panel></div><Panel title="Stock movement history" sub="Auditable record of received, sold, and adjusted quantities" className="movement-panel"><MovementTable moves={moves}/></Panel></>}

// Alerts focus the workspace on products that need action soonest.
function Alerts({products,setProducts}){const [query,setQuery]=useState(''),[filter,setFilter]=useState('All alerts');const items=products.filter(p=>p.qty<=p.min&&(p.name.toLowerCase().includes(query.toLowerCase()))&&(filter==='All alerts'||stockState(p)===filter));return <><PageHead eyebrow="ATTENTION REQUIRED" title="Low stock alerts" sub="Stay ahead of stockouts and keep your best sellers available." actions={<select className="select-compact" value={filter} onChange={e=>setFilter(e.target.value)}><option>All alerts</option><option>Low stock</option><option>Out of stock</option></select>}/><div className="alert-banner"><span><TriangleAlert size={19}/></span><div><b>{items.length} products need your attention</b><small>Restock recommendations use each product’s minimum stock level and recent sales pace.</small></div><a href="/stock">Receive stock <ArrowUpRight size={15}/></a></div><div className="alert-toolbar"><div className="table-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search products…"/></div><span>{items.length} alerts</span></div><div className="alert-card-grid">{items.map(p=><article className="alert-product-card" key={p.id}><div className="alert-card-top"><span className="product-icon big">{p.icon}</span><Status product={p}/></div><h3>{p.name}</h3><p>{p.id} · {p.category}</p><div className="alert-quantity"><div><small>Current quantity</small><strong className={p.qty===0?'negative':'orange-text'}>{p.qty}<span> units</span></strong></div><div><small>Minimum level</small><b>{p.min} units</b></div><div><small>Suggested restock</small><b>{Math.max(p.min*2-p.qty, p.sold?Math.ceil(p.sold*.25):p.min)} units</b></div></div><div className="alert-card-actions"><Button onClick={()=>location.assign('/stock')}>Update stock</Button><Button variant="primary" icon={Plus} onClick={()=>location.assign('/stock')}>Restock</Button></div></article>)}</div>{!items.length&&<div className="empty-card"><span>✓</span><h3>All clear</h3><p>No products match this alert view.</p></div>}</>}

// Prediction uses clearly labeled illustrative data until backend models exist.
function Prediction({products}){const [selected,setSelected]=useState(products[0]?.id||'');const p=products.find(x=>x.id===selected)||products[0];const hist=[{day:'Oct 28',actual:4,predicted:null},{day:'Oct 29',actual:6,predicted:null},{day:'Oct 30',actual:5,predicted:null},{day:'Oct 31',actual:8,predicted:null},{day:'Nov 01',actual:7,predicted:null},{day:'Nov 02',actual:11,predicted:null},{day:'Nov 03',actual:9,predicted:9},{day:'Nov 04',actual:null,predicted:11},{day:'Nov 05',actual:null,predicted:12},{day:'Nov 06',actual:null,predicted:14},{day:'Nov 07',actual:null,predicted:13},{day:'Nov 08',actual:null,predicted:16},{day:'Nov 09',actual:null,predicted:18}];const expected=Math.round((p?.sold||20)*.29),short=Math.max(0,expected-(p?.qty||0));return <><PageHead eyebrow="INTELLIGENCE" title="AI demand prediction" sub="Analyze historical sales and plan inventory with confidence." actions={<label className="product-select-label">PRODUCT<select value={selected} onChange={e=>setSelected(e.target.value)}>{products.map(x=><option value={x.id}>{x.name}</option>)}</select></label>}/><div className="demo-disclaimer"><BrainCircuit size={17}/><span><b>Illustrative demo prediction</b> · Values below are sample estimates. Connect a backend forecasting model (moving average or regression) for live predictions.</span></div><div className="prediction-stats"><StatCard label="Current stock" value={`${p?.qty||0} units`} change="Available now" icon={Boxes} tone="blue"/><StatCard label="Predicted 7-day demand" value={`${expected} units`} change="Estimated demand" icon={TrendingUp} tone="violet"/><StatCard label="Expected requirement" value={`${expected+Math.max(8,p?.min||8)} units`} change="Demand + safety buffer" icon={PackageCheck} tone="green"/><StatCard label="Shortage risk" value={short>0?'High':'Low'} change={short>0?`${short} units at risk`:'Stock appears sufficient'} icon={TriangleAlert} tone={short>0?'orange':'green'}/></div><div className="dashboard-grid prediction-grid"><Panel title="Historical sales & forecast" sub="Daily units · illustrative forecast for demo"><ResponsiveContainer width="100%" height={300}><LineChart data={hist}><CartesianGrid stroke="#eef1f6" vertical={false}/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize:10,fill:'#9aa4b4'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#9aa4b4'}}/><Tooltip {...chartTip}/><Line type="monotone" dataKey="actual" stroke="#4862dc" strokeWidth={2.5} dot={{r:3}} connectNulls={false} name="Historical sales"/><Line type="monotone" dataKey="predicted" stroke="#f0a449" strokeWidth={2.5} strokeDasharray="5 5" dot={{r:3}} connectNulls name="Forecast"/></LineChart></ResponsiveContainer><div className="chart-legend"><span><i className="blue-dot"/> Historical sales</span><span><i className="orange-dot"/> Demo forecast</span></div></Panel><div className="recommendation-card"><div className="rec-icon"><BrainCircuit size={19}/></div><div className="eyebrow">RESTOCK RECOMMENDATION</div><h2>{short>0?'Restock soon':'Stock looks healthy'}</h2><p>{p?.name} has a predicted 7-day demand of <b>{expected} units</b>. {short>0?`Add around ${short+8} units to cover demand and safety stock.`:'Current inventory can cover the sample demand forecast.'}</p><div className="rec-metrics"><div><small>Current stock</small><b>{p?.qty||0} units</b></div><div><small>7-day demand</small><b>{expected} units</b></div><div><small>Suggested order</small><b>{short>0?short+8:0} units</b></div></div><Button variant="primary" icon={ArrowUpRight} onClick={()=>location.assign('/stock')}>Plan a restock</Button><small className="model-footnote">Model status: demo estimates · Backend not connected</small></div></div><div className="dashboard-grid"><Panel title="Demand signals" sub="Patterns in your current demo data"><div className="signal-list"><div><span className="signal-icon green"><TrendingUp size={17}/></span><span><b>Increasing demand</b><small>Notebook, gel pen set</small></span><span className="positive">+24%</span></div><div><span className="signal-icon red"><ArrowDownRight size={17}/></span><span><b>Cooling demand</b><small>Premium document file</small></span><span className="negative">−8%</span></div><div><span className="signal-icon blue"><PackageCheck size={17}/></span><span><b>Strong performers</b><small>Gel pen set, HB pencil pack</small></span><span className="positive">Top sellers</span></div></div></Panel><Panel title="Forecast notes" sub="How to interpret this demo"><div className="forecast-notes"><div><span>01</span><p>Forecast values are sample data for product demonstration.</p></div><div><span>02</span><p>Connect an API in <code>src/services</code> to supply model output.</p></div><div><span>03</span><p>Use forecast confidence intervals before making purchase decisions.</p></div></div></Panel></div></>}

// Analytics combines period filters, charts, and CSV export in one report view.
function Analytics({products,sales}){const [period,setPeriod]=useState('Last 7 days');const cats=[...new Set(products.map(p=>p.category))].map((name,i)=>({name,value:products.filter(p=>p.category===name).reduce((a,p)=>a+p.sold*p.price,0),color:['#4e65df','#45b58b','#f0a44b','#9c82e7','#ea707b'][i%5]}));const exportCsv=()=>{const csv='Product,Category,Units sold,Revenue,Current stock\n'+products.map(p=>`${p.name},${p.category},${p.sold},${p.sold*p.price},${p.qty}`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='paperlane-analytics.csv';a.click();URL.revokeObjectURL(a.href)};return <><PageHead eyebrow="BUSINESS INTELLIGENCE" title="Analytics & reports" sub="Understand performance across sales and inventory." actions={<><select className="select-compact" value={period} onChange={e=>setPeriod(e.target.value)}><option>Today</option><option>Last 7 days</option><option>Last 30 days</option><option>This month</option></select><Button icon={Download} onClick={exportCsv}>Export report</Button></>}/><div className="stats-grid"><StatCard label="Total revenue" value={cash(sales.reduce((a,s)=>a+s.amount,0)+45700)} change="14.2%" icon={IndianRupee} tone="blue"/><StatCard label="Sales growth" value="12.8%" change="Up this period" icon={TrendingUp} tone="green"/><StatCard label="Products tracked" value={products.length} change="Across categories" icon={Package} tone="violet"/><StatCard label="Inventory value" value={cash(products.reduce((a,p)=>a+p.qty*p.cost,0))} change="At purchase cost" icon={Boxes} tone="orange"/></div><div className="dashboard-grid analytics-charts"><Panel title="Revenue trend" sub={`Revenue by day · ${period}`}><ResponsiveContainer width="100%" height={270}><AreaChart data={salesSeries}><defs><linearGradient id="revFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4e65df" stopOpacity={.18}/><stop offset="100%" stopColor="#4e65df" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#eef1f6" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false} tickFormatter={x=>`₹${x/1000}k`}/><Tooltip {...chartTip} formatter={v=>cash(v)}/><Area type="monotone" dataKey="sales" stroke="#4e65df" strokeWidth={2.5} fill="url(#revFill)"/></AreaChart></ResponsiveContainer></Panel><Panel title="Category revenue" sub="Sales contribution by category"><div className="category-chart"><ResponsiveContainer width="100%" height={190}><PieChart><Pie data={cats} dataKey="value" innerRadius={52} outerRadius={76} paddingAngle={3} stroke="none">{cats.map(x=><Cell fill={x.color} key={x.name}/>)}</Pie></PieChart></ResponsiveContainer></div><div className="legend-list">{cats.map(c=><div key={c.name}><span><i style={{background:c.color}}/>{c.name}</span><b>{cash(c.value)}</b></div>)}</div></Panel></div><div className="dashboard-grid analytics-charts"><Panel title="Daily sales" sub="Revenue comparison"><ResponsiveContainer width="100%" height={230}><BarChart data={salesSeries}><CartesianGrid stroke="#eef1f6" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false} tickFormatter={x=>`₹${x/1000}k`}/><Tooltip {...chartTip} formatter={v=>cash(v)}/><Bar dataKey="sales" fill="#526be0" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></Panel><Panel title="Product performance" sub="Top products by sales revenue"><div className="performance-bars">{[...products].sort((a,b)=>b.sold*b.price-a.sold*a.price).slice(0,5).map(p=><div key={p.id}><span className="product-icon">{p.icon}</span><span className="performance-name">{p.name}<i><b style={{width:`${(p.sold*p.price/Math.max(...products.map(x=>x.sold*x.price)))*100}%`}}/></i></span><strong>{cash(p.sold*p.price)}</strong></div>)}</div></Panel></div><Panel title="Inventory health" sub="Current stock status by product"><div className="table-scroll"><table><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>UNITS SOLD</th><th>REVENUE</th><th>STOCK STATUS</th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td><span className="table-product"><span className="product-icon">{p.icon}</span><span><b>{p.name}</b><small>{p.id}</small></span></span></td><td>{p.category}</td><td>{p.sold}</td><td>{cash(p.sold*p.price)}</td><td><Status product={p}/></td></tr>)}</tbody></table></div></Panel></>}

// Team management provides editable demo roles and statuses.
function UserManagement({users,setUsers}){const [query,setQuery]=useState(''),[form,setForm]=useState(null);const filtered=users.filter(u=>`${u.name} ${u.email}`.toLowerCase().includes(query.toLowerCase()));function save(e){e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));if(form?.email)setUsers(users.map(u=>u.email===form.email?{...u,...v}:u));else setUsers([{...v,status:'Active',date:new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})},...users]);setForm(null)}return <><PageHead eyebrow="WORKSPACE ACCESS" title="User management" sub="Manage teammates and keep workspace access up to date." actions={<Button variant="primary" icon={Plus} onClick={()=>setForm({})}>Add user</Button>}/><div className="user-summary"><div><span className="stat-icon blue"><Users size={18}/></span><span><b>{users.length} team members</b><small>Workspace access</small></span></div><div><span className="stat-icon green"><ShieldCheck size={18}/></span><span><b>{users.filter(u=>u.role==='Admin').length} administrators</b><small>Full workspace permissions</small></span></div></div><Panel title="Team members" sub="People with access to your Paperlane workspace" action={<div className="table-search"><Search size={15}/><input placeholder="Search users…" value={query} onChange={e=>setQuery(e.target.value)}/></div>}><div className="table-scroll"><table><thead><tr><th>USER</th><th>ROLE</th><th>STATUS</th><th>JOINED</th><th/></tr></thead><tbody>{filtered.map(u=><tr key={u.email}><td><div className="user-cell"><span className="avatar">{u.name[0]}</span><span><b>{u.name}</b><small>{u.email}</small></span></div></td><td><span className={`role-tag ${u.role==='Admin'?'admin':''}`}>{u.role}</span></td><td><span className="status green"><i/>Active</span></td><td>{u.date}</td><td><div className="row-actions"><button onClick={()=>setForm({...u})}><Pencil size={15}/></button><button onClick={()=>confirm(`Remove ${u.name}?`)&&setUsers(users.filter(x=>x.email!==u.email))}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div></Panel>{form&&<Modal title={form.email?'Edit teammate':'Add a teammate'} onClose={()=>setForm(null)}><form className="modal-form" onSubmit={save}><div className="form-grid"><Field label="Full name" name="name" defaultValue={form.name} required/><Field label="Email address" name="email" type="email" defaultValue={form.email} required/><label className="field"><span>Role</span><select name="role" defaultValue={form.role||'Staff'}><option>Admin</option><option>Staff</option></select></label></div><div className="modal-actions"><Button onClick={()=>setForm(null)}>Cancel</Button><Button variant="primary" type="submit">Save user</Button></div></form></Modal>}</>}

// Settings persist workspace preferences and expose the later profile fields.
function Settings(){const [saved,setSaved]=useState(false),[currency,setCurrency]=useState('INR (₹)');useEffect(()=>{const x=read('paperlane_settings',null);if(x){const form=document.querySelector('.settings-grid')?.closest('form');if(form)Object.entries(x).forEach(([k,v])=>{const el=form.elements.namedItem(k);if(el&&el.type!=='checkbox')el.value=v});setCurrency(x.currency||'INR (₹)')}},[]);function save(e){e.preventDefault();const f=new FormData(e.currentTarget),o={currency};for(const [k,v] of f.entries())if(k!=='currency')o[k]=v;o.stockAlerts=e.currentTarget.elements.stockAlerts.checked;o.salesUpdates=e.currentTarget.elements.salesUpdates.checked;o.restockReminders=e.currentTarget.elements.restockReminders.checked;localStorage.setItem('paperlane_settings',JSON.stringify(o));setSaved(true);setTimeout(()=>setSaved(false),2500)}return <><PageHead eyebrow="PREFERENCES" title="Settings" sub="Configure your business profile and workspace preferences."/><form onSubmit={save}><div className="settings-grid"><Panel title="Business profile" sub="The details that appear on your invoices"><div className="settings-form"><Field label="Business name" name="business" placeholder="Paperlane Stationery" defaultValue="Paperlane Stationery"/><Field label="Business email" name="email" type="email" placeholder="hello@paperlane.in" defaultValue="hello@paperlane.in"/><Field label="Phone number" name="phone" placeholder="+91 98765 43210" defaultValue="+91 98765 43210"/><Field label="Business address" name="address" placeholder="Street, city, PIN code" defaultValue="12 MG Road, Bengaluru, Karnataka 560001"/><label className="field"><span>Currency</span><select name="currency" value={currency} onChange={e=>setCurrency(e.target.value)}><option>INR (₹)</option><option>USD ($)</option><option>EUR (€)</option></select></label></div></Panel><Panel title="Notifications" sub="Choose which updates are useful to you"><div className="setting-toggles">{[['Stock alerts','Get notified when a product reaches its minimum level.','stockAlerts'],['Sales updates','Receive a notification when an invoice is completed.','salesUpdates'],['Restock reminders','A weekly digest of products due for restocking.','restockReminders']].map((x,i)=><label className="toggle-row" key={x[0]}><span><b>{x[0]}</b><small>{x[1]}</small></span><input name={x[2]} type="checkbox" defaultChecked={i!==2}/><i/></label>)}</div></Panel><Panel title="Security" sub="Keep your workspace account secure"><div className="security-row"><span className="security-icon"><LockKeyhole size={18}/></span><span><b>Password</b><small>Change the password associated with your account.</small></span><Button onClick={()=>alert('Password change will be available after backend authentication is connected.')}>Change password</Button></div><div className="security-row"><span className="security-icon"><ShieldCheck size={18}/></span><span><b>Role permissions</b><small>Admin and Staff roles are ready for backend enforcement.</small></span><span className="role-tag admin">Admin</span></div></Panel></div><div className="save-settings"><span>{saved&&<><Check size={16}/> Changes saved successfully</>}</span><Button variant="primary" type="submit">Save changes</Button></div></form></>}

// Export the root router for Vite's application entry point.
export default App;
